// Cloudflare entry point: the OpenNext-generated Next.js worker plus a daily cron that
// calls the app's own reminder endpoint.
// @ts-expect-error generated by `opennextjs-cloudflare build`
import { default as handler } from "./.open-next/worker.js";

type Env = { CRON_SECRET?: string; NEXT_PUBLIC_APP_URL?: string };

const worker = {
  fetch: handler.fetch,

  async scheduled(_event: unknown, env: Env, ctx: { waitUntil(p: Promise<unknown>): void }) {
    const base = (env.NEXT_PUBLIC_APP_URL || "https://lendbook.local").replace(/\/$/, "");
    const req = new Request(`${base}/api/cron/daily`, {
      headers: { Authorization: `Bearer ${env.CRON_SECRET ?? ""}` },
    });
    const res: Response = await handler.fetch(req, env, ctx);
    console.log("daily reminders:", res.status, await res.text());
  },
};

export default worker;
